#include "../Core/Snow.cpp"
#include <cassert>
#include <iostream>
double allMass(){auto d=snow_diagnostics();return d.pileArea+d.pendingArea+d.airborneArea;}
void begin(SnowWindow &w){snow_forget_windows();snow_windows_at(&w,1,10);}
void sample(SnowWindow&w,double x,double t){w.rect.x=x;snow_windows_at(&w,1,t);}
double rateFor(double dx){SnowWindow w={77,{100,200,320,80}};begin(w);sample(w,100+dx,10.1);std::fill(surfaces[77].h.begin(),surfaces[77].h.end(),12);sample(w,100+2*dx,10.2);double rate=0,area=0;for(auto b:shedding){rate+=b.rate;area+=b.area;assert(b.x>=100+dx&&b.x<420+dx);}assert(std::abs(allMass()-3840)<1e-8);assert(std::all_of(surfaces[77].h.begin(),surfaces[77].h.end(),[](double h){return h==0;}));return rate/area;}
double emitted(double dx){rateFor(dx);for(int i=0;i<4;++i)snow_step(.05,0,0);return snow_diagnostics().airborneArea;}
int main(){snow_corner_inset(0);SnowRect d={0,0,1600,1200};snow_displays(&d,1);double slow=rateFor(1),fast=rateFor(60);assert(fast>slow*2);std::cout<<"PASS motion slow/fast release rate "<<slow<<" / "<<fast<<"; all mass old-world, no rigid pile\n";
 double slowAmount=emitted(1),fastAmount=emitted(60);assert(fastAmount>2*slowAmount);std::cout<<"PASS actual production early emitted area slow="<<slowAmount<<" fast="<<fastAmount<<"\n";
 SnowWindow w={77,{100,200,320,80}};begin(w);sample(w,110,10.1);sample(w,120,10.2);double steady=surfaces[77].releaseSeconds;assert(surfaces[77].acceleration<1e-7);
 w={77,{100,200,320,80}};begin(w);sample(w,101,10.1);sample(w,111,10.2);assert(surfaces[77].acceleration>500&&surfaces[77].releaseSeconds<steady);std::cout<<"PASS same final speed sharper acceleration increases release; steady velocity has no fictitious acceleration\n";
 for(int hz:{30,60,120}){w={77,{100,200,320,80}};begin(w);for(int i=1;i<=hz;++i)sample(w,100+120.0*i/hz,10+double(i)/hz);assert(surfaces[77].acceleration<1e-5);assert(std::abs(surfaces[77].rawVx-120)<1e-7);assert(surfaces[77].vx>21&&surfaces[77].vx<=21.60001);std::cout<<"PASS actual snapshot timestamps steady motion at "<<hz<<"Hz independent of simulation clock\n";}
 for(int hz:{30,60,120}){w={77,{100,200,320,80}};begin(w);for(int i=1;i<=hz;++i){double t=double(i)/hz;sample(w,100+150*t*t,10+t);}assert(surfaces[77].acceleration>299&&surfaces[77].acceleration<301);assert(surfaces[77].releaseSeconds>.29&&surfaces[77].releaseSeconds<.33);std::cout<<"PASS filtered real acceleration at "<<hz<<"Hz remains consistent and clamped\n";}
 w={77,{100,200,320,80}};begin(w);std::fill(surfaces[77].h.begin(),surfaces[77].h.end(),12);for(int i=1;i<=120;++i)sample(w,100+(i%2?.1:-.1),10+i/120.0);assert(shedding.empty()&&surfaces[77].acceleration==0);sample(w,150,11);for(auto b:shedding)assert(b.vx==0);assert(std::isfinite(surfaces[77].acceleration));sample(w,10000,11.1);assert(surfaces[77].vx==0&&surfaces[77].acceleration==0);sample(w,10001,11);assert(surfaces[77].vx==0);sample(w,10002,std::nan(""));assert(std::isfinite(surfaces[77].vx));std::cout<<"PASS jitter, repeated/reversed/nonfinite time and teleport reset motion without throw\n";
 SnowWindow pair[2]={{77,{100,200,320,80}},{78,{600,300,200,80}}};snow_forget_windows();snow_windows_at(pair,2,20);pair[0].rect.x+=10;pair[1].rect.x+=10;snow_windows_at(pair,2,20.1);std::swap(pair[0],pair[1]);pair[0].rect.x+=10;pair[1].rect.x+=10;snow_windows_at(pair,2,20.2);assert(surfaces[77].acceleration<1e-7&&surfaces[78].acceleration<1e-7);std::cout<<"PASS stable window-ID motion history survives snapshot order changes\n";
 snow_reset();std::fill(surfaces[77].h.begin(),surfaces[77].h.end(),12);sample(w,10004,12);clumps.assign(maxClumps,{400,100,1,0,1,77});double mass=allMass();snow_step(.05,0,0);assert(std::abs(allMass()-mass)<1e-7&&clumps.size()<=maxClumps&&shedding.size()<=maxShedding&&shedLastStep<=96);std::cout<<"PASS acceleration release obeys shared grain/reservoir budgets with conservative backpressure\n";
}
